static int address(Terminal *t, int v) {
    return t->modes[ORIGIN] ? minimum(t->top + v - 1, t->bottom) : minimum(v, t->height);
    int p = count ? t->params[0] : 0, p2 = count > 1 ? t->params[1] : 0, n = maximum(p, 1);
    case 'H':
    case 'f':
        t->row = address(t, n);
        t->col = minimum(maximum(p2, 1), t->width);
        break;
    case 'd':
        t->row = address(t, n);
        break;
